/**
 * Brand logo - hand-authored from a user-supplied SVG that embeds a raster PNG
 * (Central Icons has no Hermes mark, and the source is a bitmap, not a vector).
 * Because it is a raster it does NOT recolour with `currentColor` like the
 * generated icons - it renders the bitmap at 20% opacity to read as a quiet,
 * muted glyph beside its label. `useId` keeps the pattern/clip ids unique so
 * multiple instances (trigger + list item) don't collide.
 */
import { memo, useId } from 'react'

import { cn } from '#lib/cn'
import { type IconProps, IconSize, iconSizeValues } from '../types'

const HERMES_PNG =
  'data:image/png;base64,'

export const IconHermes = memo(function IconHermes({
  size = IconSize.Medium,
  title,
  className,
  ref,
  ...props
}: IconProps) {
  const px = iconSizeValues[size]
  const maskId = `hermes-mask-${useId()}`

  // The PNG is the alpha mask; a `currentColor` rect paints through it, so the
  // glyph renders as a solid silhouette in the icon's colour (matching the
  // generated marks) instead of the bitmap's own tones.
  return (
    <svg
      width={px}
      height={px}
      viewBox="0 0 24 24"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      role={title ? 'img' : undefined}
      aria-label={title}
      aria-hidden={title ? undefined : true}
      className={cn('shrink-0', className)}
      ref={ref}
      {...props}
    >
      <defs>
        <mask
          id={maskId}
          maskUnits="userSpaceOnUse"
          x="0"
          y="0"
          width="24"
          height="24"
          style={{ maskType: 'alpha' }}
        >
          <image
            width="24"
            height="24"
            preserveAspectRatio="xMidYMid meet"
            href={HERMES_PNG}
          />
        </mask>
      </defs>
      <rect
        width="24"
        height="24"
        fill="currentColor"
        mask={`url(#${maskId})`}
      />
    </svg>
  )
})
